from pathlib import Path
import subprocess,json,statistics,random
p=Path(__file__).parent;root=Path('/tmp');lcp=root/'sirkit_rh_lcp_strategy_20261023/api.cpp';fixed=root/'sirkit_rolling_hash_core_20261023/fixed_api.cpp';configs={'gcc_native':['/usr/bin/g++','-march=native'],'clang_standard':['/usr/bin/clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15']};variants=['baseline','candidate'];rows=[];rng=random.Random(987031)
for conf,cc in configs.items():
 for mode in [0,1,6,7,8,14,15]:
  for v in variants:
   src=lcp if mode<2 else fixed;exe=p/f'{conf}_{v}_{mode}';cmd=['taskset','-c','24',*cc,'-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS',f'-DSOURCE="{p/(v+".hpp")}"',f'-DOP={mode}',f'-DSIRKIT_MODE={mode}',str(src),'-o',str(exe)];o=subprocess.run(cmd,capture_output=True,text=True);assert o.returncode==0,o.stderr
 print(conf,'compiled',flush=True)
 for n in [31,4097,1048576]:
  scenarios=[(0,pat)for pat in [0,1,2,3,8,9]]+[(1,pat)for pat in [0,2,3,8,9]]+[(m,0)for m in [6,7,8,14,15]]
  for mode,pat in scenarios:
   times={v:[]for v in variants};checks={v:[]for v in variants}
   args=[str(n),str(pat),str(32768)]if mode<2 else[str(n),'0','128'if n<100 else'16'if n<10000 else'3']
   for rep in range(5):
    order=variants.copy();rng.shuffle(order)
    for v in order:
     o=subprocess.run(['taskset','-c','20',str(p/f'{conf}_{v}_{mode}'),*args],capture_output=True,text=True);assert o.returncode==0,(mode,pat,o.stderr)
     ns,checksum=o.stdout.split();times[v].append(float(ns));checks[v].append(checksum)
    assert checks['baseline'][-1]==checks['candidate'][-1],(conf,mode,pat,n,checks)
   med={v:statistics.median(x)for v,x in times.items()};row=dict(config=conf,n=n,mode=mode,pattern=pat,raw=times,median_ns=med,ratio=med['candidate']/med['baseline']);rows.append(row);(p/'screen-results.json').write_text(json.dumps(rows,indent=2));print(conf,n,mode,pat,round(row['ratio'],3),flush=True)

